def prime_factors(n):
    factors = []
    # Handle factor 2 separately to allow increment by 2 later
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Check odd factors starting from 3
    f = 3
    while f * f <= n:
        while n % f == 0:
            factors.append(f)
            n //= f
        f += 2

    if n > 1:
        factors.append(n)

    return factors

